begin;
select plan(15);
insert into auth.users(id,email)values('a1000000-0000-4000-8000-000000000001','skip-route-office@test.invalid');
insert into public.user_profiles(user_id,display_name)values('a1000000-0000-4000-8000-000000000001','SKIP Route Office');
insert into app_private.user_roles(user_id,role_id)select'a1000000-0000-4000-8000-000000000001'::uuid,role_id from app_private.roles where role_key='director_admin';
insert into app_private.service_regions(service_region_id,name,region_code)values('a2000000-0000-4000-8000-000000000001','SKIP Route Region','SKIP_R');
insert into app_private.user_access_scopes(user_id,scope_kind,scope_id)values('a1000000-0000-4000-8000-000000000001','global',null);
insert into app_private.depots(depot_id,service_region_id,name,address_line_1,suburb,city)values('a3000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','SKIP Depot','1 Synthetic Road','Test','Pretoria');
insert into app_private.vehicles(vehicle_id,service_region_id,default_depot_id,registration_reference,display_name,estimated_drum_capacity)values('a4000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','SKIP-01','SKIP Vehicle',4);
insert into app_private.teams(team_id,service_region_id,default_depot_id,team_code,name,normal_vehicle_id,working_hours)values('a5000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','SKIP_A','SKIP Team','a4000000-0000-4000-8000-000000000001','{"maxMinutes":60}');
insert into app_private.staff(staff_id,display_name,operational_role,default_team_id)values('a6000000-0000-4000-8000-000000000001','SKIP Driver','driver','a5000000-0000-4000-8000-000000000001');
insert into app_private.territories(territory_id,service_region_id,name)values('a7000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','SKIP Territory');
insert into app_private.territory_eligible_teams values('a7000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001',now());
insert into app_private.operational_days(operational_day_id,service_date,service_region_id,timezone,lifecycle_status,locked_at,locked_by)values('a8000000-0000-4000-8000-000000000001','2026-08-20','a2000000-0000-4000-8000-000000000001','Africa/Johannesburg','locked',now(),'a1000000-0000-4000-8000-000000000001');
insert into app_private.daily_roster_entries(daily_roster_entry_id,operational_day_id,team_id,normal_vehicle_id,assigned_vehicle_id,normal_depot_id,assigned_depot_id)values('a9000000-0000-4000-8000-000000000001','a8000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001');
insert into app_private.daily_roster_staff_assignments(daily_roster_entry_id,staff_id,expected_team_id,assignment_role)values('a9000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','driver');
insert into app_private.clients(client_id,client_type,display_name,lifecycle_status,activated_at)values('aa000000-0000-4000-8000-000000000001','individual','SKIP Route Client','active',now());
insert into app_private.client_contacts(client_contact_id,client_id,contact_name,mobile_e164,email,is_primary)values('aa100000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001','SKIP Contact','+27820000411','skip-route@example.invalid',true);
insert into app_private.service_addresses(service_address_id,address_line_1,suburb,city,latitude,longitude)values('ab000000-0000-4000-8000-000000000001','10 SKIP Route','Test','Pretoria',-25.75,28.20);
insert into app_private.client_services(client_service_id,client_id,service_address_id,lifecycle_status,service_start_date,cadence_code)values('ac000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001','ab000000-0000-4000-8000-000000000001','active','2026-01-01','weekly');
insert into app_private.service_configurations(service_configuration_id,client_service_id,service_region_id,territory_id,default_team_id,configured_drum_count,operational_drum_unit_count,configured_collection_day,effective_from)values('ad000000-0000-4000-8000-000000000001','ac000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001',2,2,4,'2026-01-01');
select lives_ok($$select api.route_generate('a1000000-0000-4000-8000-000000000001','a8000000-0000-4000-8000-000000000001',gen_random_uuid(),false,null,null)$$,'real route generator includes eligible occurrence');
select is((select count(*)from app_private.planned_route_stops),1::bigint,'service initially routed');
select lives_ok($$select api.route_transition('a1000000-0000-4000-8000-000000000001',(select route_version_id from app_private.route_versions),'ready',(select updated_at from app_private.route_versions),gen_random_uuid())$$,'route becomes Ready');
select lives_ok($$select api.route_transition('a1000000-0000-4000-8000-000000000001',(select route_version_id from app_private.route_versions),'published',(select updated_at from app_private.route_versions),gen_random_uuid())$$,'route publishes');
select lives_ok($$select api.route_operations_handoff('a1000000-0000-4000-8000-000000000001',(select route_version_id from app_private.route_versions where version_status='published'),gen_random_uuid())$$,'Published route handed to operations');
update app_private.route_operations set lifecycle_status='accepted',accepted_at=now(),accepted_by='a1000000-0000-4000-8000-000000000001';
select api.communication_ingest_inbound('fake-communications','whatsapp','skip-route-1','+27820000411','2026-08-19T08:00:00+02','SKIP',gen_random_uuid());
select api.client_skip_consume_inbound((select inbound_message_id from app_private.inbound_messages where provider_message_id='skip-route-1'),gen_random_uuid());
select lives_ok($$select api.client_skip_approve('a1000000-0000-4000-8000-000000000001',(select client_skip_request_id from app_private.client_skip_requests),1,'Approved before service',gen_random_uuid())$$,'one-day exclusion approved');
select is((select version_status from app_private.route_versions),'published','Published route remains immutable');
select is((select lifecycle_status from app_private.route_operations),'accepted','accepted operation remains intact');
select lives_ok($$select api.client_skip_replan('a1000000-0000-4000-8000-000000000001',(select client_skip_request_id from app_private.client_skip_requests),'Create replacement Draft',gen_random_uuid())$$,'controlled replan creates replacement');
select is((select count(*)from app_private.route_versions),2::bigint,'old version preserved and new version added');
select is((select count(*)from app_private.planned_route_stops s join app_private.route_versions v using(route_version_id)where v.version_status='draft'),0::bigint,'replacement Draft excludes skipped occurrence');
select is((select reason_code from app_private.unassigned_route_services u join app_private.route_versions v using(route_version_id)where v.version_status='draft'),'client_requested_skip','excluded work has stable reason');
select is((select lifecycle_status from app_private.route_operations),'accepted','replanning still does not mutate Route Operation');
select is((select count(*)from app_private.needs_attention_items),1::bigint,'active-operation conflict creates one Needs Attention item');
select is((select lifecycle_status from app_private.client_services where client_service_id='ac000000-0000-4000-8000-000000000001'),'active','future recurring service remains active');
select * from finish();rollback;
